if (msg.statusCode === 202) {
    flow.set('run_id', msg.payload.run_id);
    msg.payload = 'Execução ' + msg.payload.run_id + ' iniciada (Pentaho Kitchen).';
} else if (msg.statusCode === 409) {
    msg.payload = 'Já existe uma execução ativa: ' + (msg.payload.detail?.active?.run_id || '');
} else {
    msg.payload = 'Erro ao contactar a API /ops (HTTP ' + msg.statusCode + ')';
}
return msg;

msg.method = 'POST';
msg.url = env.get('API_URL') + '/ops/runs';
msg.headers = { 'X-API-Key': env.get('OPS_API_TOKEN'), 'Content-Type': 'application/json' };
msg.payload = { job: 'main' };
return msg;

const order = [['EXTRACT','Extração + Transformação'],['CORRELATE','Correlação'],['RULES','Regras'],
               ['AI','IA (Qwen3)'],['EVALUATE','Avaliação'],['EXPORT','Persistência / Exportação'],
               ['NOTIFY','Notificação (e-mail)']];
const rows = msg.payload || [];
const stages = order.map(([k, label]) => {
    const r = rows.find(x => x.stage === k);
    return { key: k, label, status: r ? r.status : 'PENDENTE', rows: r ? r.rows_processed : null };
});
msg.payload = { run: msg.run, stages };
return msg;

const r = (msg.payload || [])[0];
if (!r) { return [{ payload: { run: null, stages: [] } }, null, null]; }
const m1 = { params: [r.run_id], run: r };
const m2 = { method: 'GET', url: env.get('API_URL') + '/ops/runs/' + r.run_id + '/log?lines=14' };
m2.headers = { 'X-API-Key': env.get('OPS_API_TOKEN') };
return [null, m1, m2];

query:
SELECT run_id, status, trigger_source, to_char(started_at, 'DD/MM HH24:MI:SS') AS inicio,
       to_char(finished_at, 'HH24:MI:SS') AS fim, error_message
FROM etl_run ORDER BY requested_at DESC LIMIT 1;

