if (msg.statusCode === 200) {
    const cfg = msg.payload;
    const toForm = { payload: { smtp_host: cfg.smtp_host, smtp_port: cfg.smtp_port, smtp_user: cfg.smtp_user,
                                smtp_password: '', mail_from: cfg.mail_from, mail_to: cfg.mail_to } };
    const note = msg.method === 'GET' ? null : { payload: msg.method === 'DELETE'
        ? 'Configuração reposta a partir do .env' : 'Configuração de e-mail guardada. Será usada na próxima execução do ETL.' };
    return [{ payload: cfg }, toForm, note];
}
const d = msg.payload && msg.payload.detail;
const why = Array.isArray(d) ? d.map(e => (e.loc || []).slice(-1)[0] + ': ' + e.msg).join('; ') : JSON.stringify(d || msg.payload);
return [null, null, { payload: 'Configuração rejeitada pela API (HTTP ' + msg.statusCode + '): ' + why }];

const f = msg.payload || {};
msg.method = 'PUT';
msg.url = env.get('API_URL') + '/ops/mail-settings';
msg.headers = { 'X-API-Key': env.get('OPS_API_TOKEN'), 'Content-Type': 'application/json' };
msg.payload = { smtp_host: String(f.smtp_host || '').trim(), smtp_port: Number(f.smtp_port),
                smtp_user: String(f.smtp_user || '').trim(), smtp_password: f.smtp_password || '',
                mail_from: String(f.mail_from || '').trim(), mail_to: String(f.mail_to || '').trim() };
return msg;

msg.method = 'GET';
msg.url = env.get('API_URL') + '/ops/mail-settings';
msg.headers = { 'X-API-Key': env.get('OPS_API_TOKEN'), 'Content-Type': 'application/json' };
delete msg.payload;
return msg;

msg.method = 'DELETE';
msg.url = env.get('API_URL') + '/ops/mail-settings';
msg.headers = { 'X-API-Key': env.get('OPS_API_TOKEN'), 'Content-Type': 'application/json' };
delete msg.payload;
return msg;

const r = msg.payload[0];
msg.payload = [
 {label:'Acessos (CSV)', value:r.acc}, {label:'Sensores (API REST)', value:r.sen},
 {label:'Simulados (dashboard)', value:r.sim}, {label:'Rejeitados (qualidade)', value:r.rej}];
return msg;

if (msg.statusCode === 201) {
    msg.payload = 'Evento ' + msg.payload.queued.event_id + ' em fila (' + msg.payload.pending + ' pendente(s)). Será processado na próxima execução do ETL.';
} else {
    msg.payload = 'Evento rejeitado pela API (HTTP ' + msg.statusCode + '): ' + JSON.stringify(msg.payload.detail || msg.payload);
}
return msg;

const f = msg.payload || {};
msg.method = 'POST';
msg.url = env.get('API_URL') + '/gateway/sensors/events';
msg.headers = { 'X-API-Key': env.get('OPS_API_TOKEN'), 'Content-Type': 'application/json' };
msg.payload = { sensor_id: String(f.sensor_id || '').trim().toUpperCase(),
                event_type: String(f.event_type || 'MOTION').trim().toUpperCase() };
return msg;

const r = msg.payload[0];
msg.payload = [ {label:'Eventos processados', value:r.events}, {label:'Casos correlacionados', value:r.cases},
  {label:'Incidentes (regras)', value:r.inc_rules}, {label:'Incidentes (IA)', value:r.inc_ai},
  {label:'Análises IA válidas', value:r.ai_ok}, {label:'Latência média IA (s)', value:r.ai_lat} ];
return msg;

query:
SELECT source AS "Fonte", source_record_id AS "Registo", reason_code AS "Motivo",
       left(raw_record, 90) AS "Registo original", run_id AS "Execução"
FROM dq_rejection ORDER BY rejected_at DESC, source_record_id LIMIT 50;
